# Application Context decorator to wrap decorated methods
# and ensure current application context is appropriate to the
# current PageObject function that is being called.

from functools import wraps
from .aut_manager import get_aut_name_of_current_context, set_app_context
import logging
import squishtest as sq

#ToT=Yes
def app_ctx_function():
#     Provides a wrapper for the given function that manages Application Context.
#
#     Typically the wrapped function will belong to a PageObject that inherits from a
#     Base class that has the function use_application available.
#     The wrapped function will be called after a call to the use_application function,
#     which in turn calls ApplicationManager to effect the context switch.
#
#     Args:
#         No arguments.
#
#     Returns:
#         Decorated function.
#

    def decorator(function):
        #Make and return wrapper function
        def wrapper(self, *args, **kwargs):
            #print "In wrapper"
			#Switch application context if necessary.
			#See BaseUIPageObject class
            self.use_application()
            #print "before function call"
            return function(self, *args, **kwargs)
            #print "after function call"
        return wrapper
    return decorator

