def set_separate_app_context(application_name: str):
    """
    A decorator function used to set Squish's current application context
    to the application name provided in the argument, mainly for test
    reporting purposes.

    This is a separate application context setter for apps that Squish
    does not directly interact with (i.e. electron apps for Integrated
    Console (IC)). This ensures that Squish's test report displays the
    correct embedded app screenshots for failed verification steps when
    switching between different apps in a workflow (e.g. IC /Integrity)

    This decorator is intended to be used as part of the python behave
    (BDD) format, before a step definition, which is the function to
    be wrapped.

    Args:
        application_name (str): Application name that Squish will set
        the current application context to

    Returns:
        None
    """
    def decorator(function):
        # Function wrapper
        def func_wrapper(*args, **kwargs):
            # Set the app context inside function wrapper
            # (before the wrapped function is called)
            if get_aut_name_of_current_context() != application_name:
                set_app_context(application_name)

            # Call the wrapped function (e.g. BDD behave step definition)
            return function(*args, **kwargs)
        return func_wrapper
    return decorator

def apply_app_context(application_name:str):
    """
    Decorator that applies app context of application to class members, and handle only
    instance methods.

    :param: application_name (str), the application name used to mark the app context
    """
    def class_decorator(cls):
        for attr_name, attr_value in cls.__dict__.items():
            if callable(attr_value) and not attr_name.startswith("__"):
                decorated = set_separate_app_context(application_name)(attr_value)
                setattr(cls, attr_name, decorated)
        return cls
    return class_decorator

def apply_app_context_ex(application_name:str):
    """
    Decorator that applies app context of application to members of a class, and extends
    the class decorator to handle instance methods, static methods, and class methods.

    :param: application_name (str), the application name used to mark the app context
    """
    def class_decorator(cls):
        for attr_name, attr_value in cls.__dict__.items():
            # Handle staticmethod
            if isinstance(attr_value, staticmethod):
                original_func = attr_value.__func__
                decorated_func = set_separate_app_context(application_name)(original_func)
                setattr(cls, attr_name, staticmethod(decorated_func))

            # Handle classmethod
            elif isinstance(attr_value, classmethod):
                original_func = attr_value.__func__
                decorated_func = set_separate_app_context(application_name)(original_func)
                setattr(cls, attr_name, classmethod(decorated_func))

            # Handle regular instance method
            elif callable(attr_value) and not attr_name.startswith("__"):
                decorated_func = set_separate_app_context(application_name)(attr_value)
                setattr(cls, attr_name, decorated_func)

        return cls
    return class_decorator

